#!/usr/bin/env python3
"""Writes po/extension-strings.vala with the user-visible strings of the
bundled extensions (data/extensions/*.json) so xgettext can extract them.
The file is never compiled. Run it after changing an extension, before
`ninja -C build sxpilot-pot`."""
import json
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent
lines = [
    "/* Generated by po/extension-strings.py; do not edit. Never compiled:",
    " * it only lists the bundled extensions' strings for xgettext. */",
]
for path in sorted((root / "data" / "extensions").glob("*.json")):
    ext = json.loads(path.read_text())
    strings = [ext.get("name"), ext.get("description"), ext.get("hint")]
    strings += [p.get("label") for p in ext.get("params", [])]
    for m in ext.get("metrics", []):
        strings.append(m.get("label"))
        strings.append(m.get("alert", {}).get("message"))
    lines.append("")
    lines.append("/* %s */" % path.name)
    for s in strings:
        if s:
            lines.append("N_(%s);" % json.dumps(s, ensure_ascii=False))
(root / "po" / "extension-strings.vala").write_text("\n".join(lines) + "\n")
